import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"1.1 明确首个场景与真实任务","description":"确定首个用户、任务族、非目标和验收任务。","frontmatter":{"title":"1.1 明确首个场景与真实任务","description":"确定首个用户、任务族、非目标和验收任务。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1/1-1.md","filePath":"delivery/stage-1/1-1.md","lastUpdated":null}'),r={name:"delivery/stage-1/1-1.md"};function o(n,e,s,d,_,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_1-1-明确首个场景与真实任务" tabindex="-1">1.1 明确首个场景与真实任务 <a class="header-anchor" href="#_1-1-明确首个场景与真实任务" aria-label="Permalink to &quot;1.1 明确首个场景与真实任务&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>确定 Hearth 首先为谁解决什么问题，并把这个问题变成一组可以验收的真实任务。阶段结束时，团队应当能说清楚首个用户、首个任务族、明确不做什么，以及什么结果算完成。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>找到一位愿意提供真实任务和反馈的首位用户，记录他每天重复做、最希望交给系统的工作。</li><li>收集 20–30 个真实任务，从中选出 10–12 个输入、产物和验收方式都清楚的任务。</li><li>只选一个高频、外部风险低、结果容易检查的任务族作为首个范围。</li><li>写出一句话定位和“暂不做什么”清单，避免第一阶段被新想法带偏。</li><li>记录这些任务现在怎么做、花多少时间、哪里容易出错，作为后续对比。</li><li>确定 MVP 的验收方式：至少 8 个真实任务通过验收，失败任务能说明原因并恢复。</li></ol>',5)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
